<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { ReviewSubmission } from '../types'
import { companyAuditStatusLabel, companyAuditVerdictLabel } from '../companyAudit'
const props = defineProps<{ item: ReviewSubmission; media?: { duration: string; resolution: string } }>()
const active = ref('progress')
watch(() => props.item.takeover?.active, value => { if (value) active.value = 'human' }, { immediate: true })
const tabs = [{ key: 'issues', label: '命中问题' }, { key: 'progress', label: '完整进度' }, { key: 'human', label: '人工审核' }, { key: 'notifications', label: '飞书通知' }]
const audit = computed(() => props.item.company_audit)
const completed = computed(() => audit.value?.status === 'success' && audit.value.ready !== false && !audit.value.verification_pending && !audit.value.error_code)
const verdict = computed(() => props.item.takeover?.active ? `人工接管 · ${props.item.status === 'approved' ? '已通过' : props.item.status === 'rejected' ? '未通过' : '审核中'}` : audit.value ? companyAuditVerdictLabel(audit.value) : '暂无公司审核记录')
const stage = computed(() => props.item.takeover?.active ? '超时人工接管' : !audit.value ? '未送公司审核' : completed.value ? '公司结果已同步' : companyAuditStatusLabel(audit.value.status))
const tone = computed(() => !completed.value ? 'neutral' : audit.value?.verdict === 'pass' ? 'pass' : audit.value?.verdict === 'reject' ? 'reject' : 'warning')
const storage = computed(() => (({ stored: '已入库', deleted: '回收站', purged: '已清理' } as Record<string, string>)[props.item.asset_storage_status || ''] || '待确认'))
const human = computed(() => props.item.decisions.some(d => d.status === 'rejected') ? '复核不通过' : props.item.decisions.length && props.item.decisions.every(d => d.status === 'approved') ? '复核通过' : props.item.human_review_disabled ? '人工审核已关闭' : props.item.decisions.some(d => d.status === 'pending') ? '待人工复核' : '无需人工复核')
const utcTime = (value: string) => new Date(/Z$|[+-]\d\d:\d\d$/.test(value) ? value : value + 'Z').getTime()
const date = (value?: string | null) => {
  if (!value) return '暂无记录'
  const parsed = new Date(/Z$|[+-]\d\d:\d\d$/.test(value) ? value : value + 'Z')
  return Number.isNaN(parsed.getTime()) ? '暂无记录' : parsed.toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false })
}
const progress = computed(() => [
  { label: '等待送审', done: Boolean(audit.value) },
  { label: '服务受理', done: Boolean(audit.value?.task_id) },
  { label: '审核中', done: Boolean(audit.value && ['processing', 'success'].includes(audit.value.status)) },
  { label: '结果已同步', done: completed.value },
])
const events = computed(() => {
  const rows = [{ name: props.item.submitted_by_name || '提交人', text: '已提交素材审核', at: props.item.submitted_at }]
  if (props.item.takeover?.started_at) rows.push({ name: props.item.takeover.actor_name || '审核人', text: '公司审核超时，已接管人工审核；公司任务继续保留', at: props.item.takeover.started_at })
  if (audit.value?.created_at) rows.push({ name: '系统', text: '已创建公司初审任务', at: audit.value.created_at })
  if (audit.value?.last_checked_at) rows.push({ name: '公司审核', text: `${stage.value} · ${verdict.value}`, at: audit.value.last_checked_at })
  for (const d of props.item.decisions) if (d.decided_at) rows.push({ name: d.reviewer_name || d.role_label, text: `${d.role_label} · ${d.status === 'approved' ? '复核通过' : d.status === 'rejected' ? '复核不通过' : '待复核'}${d.note ? '：' + d.note : ''}`, at: d.decided_at })
  return rows.sort((a,b) => utcTime(a.at) - utcTime(b.at))
})
</script>
<template>
  <div class="audit-detail"><p v-if="item.acceptance_example" class="result-box">验收示例：视频为本地样本，结论为隔离场景数据，仅用于产品验收，不能执行审批或回传。</p>
    <header class="material-title"><div><small>素材审核 · 公司初审 / 人工复审</small><h2>{{ item.asset_name }}</h2><p>{{ item.submitted_by_name || '未记录提交人' }} · 第 {{ item.version }} 版</p></div><span :class="['badge', tone]">{{ verdict }}</span></header>
    <slot name="takeover" /><section class="media-information"><div class="sent-video"><h3>送审视频</h3><slot name="video" /></div><div><h3>素材信息</h3><dl class="asset-facts"><dt>原始文件</dt><dd>{{ item.filename_snapshot || item.asset_name }}</dd><dt>素材分类</dt><dd>{{ item.asset_category || '未分类' }}</dd><dt>所属产品编码</dt><dd>{{ audit?.product_id || '未配置' }}</dd><dt>提交人员</dt><dd>{{ item.submitted_by_name || '未记录' }}</dd><dt>产出团队</dt><dd>{{ [item.route_center, item.route_group].filter(Boolean).join(' / ') || '未提供' }}</dd><dt>视频时长</dt><dd>{{ media?.duration || '等待视频元数据' }}</dd><dt>分辨率</dt><dd>{{ media?.resolution || '等待视频元数据' }}</dd><dt>文件大小</dt><dd>{{ item.asset_size ? (item.asset_size / 1024 / 1024).toFixed(2) + ' MB' : '未提供' }}</dd></dl><p class="material-note">{{ item.note || '暂无备注' }}</p></div></section>
    <div class="detail-metrics"><div><span>命中问题</span><strong>{{ audit?.findings.length ?? 0 }} 项</strong></div><div><span>处理阶段</span><strong>{{ stage }}</strong></div><div><span>复审状态</span><strong>{{ human }}</strong></div><div><span>入库状态</span><strong>{{ storage }}</strong></div></div>
    <ol class="company-progress" aria-label="公司初审进度"><li v-for="(step, index) in progress" :key="step.label" :class="{ done: step.done }"><i>{{ step.done ? '✓' : index + 1 }}</i><span>{{ step.label }}</span></li></ol>
    <p class="result-summary">{{ audit?.summary || (audit ? '公司审核尚未返回问题摘要' : '本次暂无公司审核记录') }}</p><p v-if="audit?.product_mapping_missing" class="muted">本次未配置公司产品编码，产品维度的明星授权检查可能不完整。</p>
    <dl class="audit-record"><dt>提交时间</dt><dd>{{ date(item.submitted_at) }}</dd><dt>最近同步</dt><dd>{{ date(audit?.last_checked_at) }}</dd><dt>人工完成时间</dt><dd>{{ date(item.completed_at) }}</dd><dt>下次执行</dt><dd>{{ audit?.next_attempt_at ? date(audit.next_attempt_at) : '暂无计划信息' }}</dd><dt>外部任务号</dt><dd>{{ audit?.task_id || '尚未分配' }}</dd><dt>公司审核记录 ID</dt><dd>{{ audit?.id || '暂无记录' }}</dd><dt>素材 ID</dt><dd>{{ item.asset_id }}</dd><dt>送审记录 / 版本</dt><dd>{{ item.id }} / 第 {{ item.version }} 版</dd></dl>
    <nav class="detail-tabs" role="tablist" aria-label="审核详情记录"><button v-for="tab in tabs" :id="'audit-tab-' + tab.key" :key="tab.key" type="button" role="tab" :aria-selected="active === tab.key" :aria-controls="'audit-panel-' + tab.key" :class="{ active: active === tab.key }" @click="active = tab.key"><span>{{ tab.label }}</span></button></nav>
    <section v-show="active === 'progress'" id="audit-panel-progress" role="tabpanel" aria-labelledby="audit-tab-progress"><ol class="event-history"><li v-for="(event,index) in events" :key="index"><strong>{{ event.name }}</strong><p>{{ event.text }}</p><time>{{ date(event.at) }}</time></li></ol><div class="result-box"><strong>公司初审结果</strong><span :class="['badge',tone]">{{ verdict }}</span><p>{{ audit?.summary || '暂无公司审核结论' }}</p></div></section>
    <section v-show="active === 'issues'" id="audit-panel-issues" role="tabpanel" aria-labelledby="audit-tab-issues"><h3>公司审核问题</h3><slot name="company" /><h3>命名规范检查</h3><slot name="naming" /></section>
    <section v-show="active === 'human'" id="audit-panel-human" role="tabpanel" aria-labelledby="audit-tab-human"><h3>人工复审</h3><slot name="human" /><p v-if="!item.can_review" class="result-box">{{ human }}。{{ item.human_review_disabled ? '历史记录保留，当前不新增人工处理。' : '当前账号暂无可执行的审核操作。' }}</p><div v-for="decision in item.decisions" :key="decision.role_code" class="decision-row"><strong>{{ decision.role_label }}</strong><span>{{ decision.status === 'approved' ? '复核通过' : decision.status === 'rejected' ? '复核不通过' : '待复核' }} · {{ decision.reviewer_name || decision.candidate_reviewers.map(r => r.user_name).join(' / ') || '待配置' }}</span><p>{{ decision.note || '暂无复核说明' }}</p><small>{{ date(decision.decided_at) }}</small></div></section>
    <section v-show="active === 'notifications'" id="audit-panel-notifications" role="tabpanel" aria-labelledby="audit-tab-notifications"><p class="result-box">暂无可展示的飞书通知记录，发送状态尚未确认。</p></section>
    <section class="detail-bottom"><h3>公司审核问题</h3><div class="result-box">{{ audit?.findings.length ? `公司审核命中 ${audit.findings.length} 项问题，可在“命中问题”中查看依据并定位视频。` : completed ? '公司结果未返回命中问题明细。' : '尚无已完成的公司审核问题记录。' }}</div><h3>人工复核说明</h3><div class="result-box human-note">{{ item.decisions.filter(d => d.note).map(d => `${d.role_label}：${d.note}`).join('；') || human }}</div></section>
  </div>
</template>
<style scoped>
.audit-detail{color:#273448;font-size:13px;line-height:1.6}.material-title{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:12px 0 20px}.material-title small{color:#2478c2;font-weight:600}.material-title h2{font-size:23px;line-height:1.4;margin:5px 0;color:#142139;overflow-wrap:anywhere}.material-title p{color:#8490a2;margin:4px 0}.badge{display:inline-block;white-space:nowrap;padding:4px 10px;border-radius:4px;font-size:12px;background:#eff2f6;color:#7e899b}.badge.pass{background:#ecf8e8;color:#59a83e}.badge.reject{background:#fff0f1;color:#c74854}.badge.warning{background:#fff3df;color:#b77b24}h3{font-size:14px;margin:0 0 12px}.media-information{display:grid;grid-template-columns:1.1fr 1fr;gap:24px;padding:16px;border:1px solid #e1e7f0;border-radius:10px;background:#f7f9fd}.media-information>div{min-width:0}.asset-facts{display:grid;grid-template-columns:88px minmax(0,1fr);gap:8px;margin:0;font-size:12px}.asset-facts dt{color:#8a94a3}.asset-facts dd{margin:0;overflow-wrap:anywhere}.material-note{border-top:1px solid #e3e8f0;padding-top:12px;margin-top:12px;font-size:12px}.detail-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0}.detail-metrics>div{display:grid;gap:3px;border:1px solid #e2e7ef;border-radius:8px;padding:12px 16px}.detail-metrics span{font-size:12px;color:#8c96a5}.detail-metrics strong{font-size:15px;color:#1c2940}.company-progress{display:flex;padding:6px 0 0;margin:24px 0;list-style:none}.company-progress li{position:relative;flex:1;display:grid;justify-items:center;gap:8px;color:#a1aab7}.company-progress li:before{content:'';position:absolute;top:12px;left:-50%;width:100%;height:2px;background:#dfe5ee}.company-progress li:first-child:before{display:none}.company-progress li i{z-index:1;display:grid;place-items:center;width:23px;height:23px;border:1px solid currentColor;border-radius:50%;background:#fff;font-style:normal}.company-progress li.done{color:#65b542}.company-progress li.done:before{background:#65b542}.result-summary{font-weight:600;margin-bottom:6px}.muted{color:#8995a6;font-size:12px}.audit-record{display:grid;grid-template-columns:110px minmax(0,1fr) 110px minmax(0,1fr);margin:18px 0 24px;border-top:1px solid #e1e7ef;border-left:1px solid #e1e7ef;font-size:12px}.audit-record dt,.audit-record dd{margin:0;padding:7px 10px;border-right:1px solid #e1e7ef;border-bottom:1px solid #e1e7ef;overflow-wrap:anywhere}.audit-record dt{background:#f5f7fb;font-weight:600}.detail-tabs{display:flex;gap:24px;border-bottom:1px solid #dde5ef;margin:22px 0 18px}.detail-tabs button{border:0;border-bottom:2px solid transparent;background:none;padding:8px 0;color:#586579;cursor:pointer}.detail-tabs button.active{color:#2987cf;border-bottom-color:#2987cf}.event-history{list-style:none;padding:0 0 0 22px;margin:0}.event-history li{position:relative;border-left:1px solid #dce6f0;padding:0 0 20px 22px}.event-history li:before{content:'';position:absolute;left:-6px;top:4px;width:11px;height:11px;background:#429fea;border-radius:50%}.event-history p{margin:2px 0}.event-history time{color:#8b97a9}.result-box{padding:16px 20px;background:#f7f9fd;border:1px solid #e1e7f0;border-radius:9px;margin:12px 0}.result-box>.badge{margin-left:14px}.result-box p{margin:6px 0 0}.detail-bottom{margin-top:24px}.detail-bottom h3{margin:20px 0 8px}.human-note{border-color:#d8e8f9;background:#f3f8ff}.decision-row{border-bottom:1px solid #e5ebf2;padding:14px 0}.decision-row>span{margin-left:14px}.decision-row p{margin:5px 0}.decision-row small{color:#8c98a9}
@media(max-width:700px){.material-title{align-items:flex-start;flex-direction:column}.media-information{grid-template-columns:1fr}.detail-metrics{grid-template-columns:repeat(2,1fr)}.audit-record{grid-template-columns:100px minmax(0,1fr)}.detail-tabs{gap:16px}.company-progress{font-size:11px}.material-title h2{font-size:19px}}
/* Isolate modal tabs from the shared navigation button and active-pill styles. */
.audit-detail .detail-tabs[role=tablist]{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;padding:0;border-bottom:1px solid #dde5ef}
.audit-detail .detail-tabs>button[role=tab]{display:flex;align-items:center;justify-content:center;text-align:center!important;min-width:0;width:100%;height:44px;margin:0;padding:10px 4px!important;box-sizing:border-box;border:0!important;border-bottom:2px solid transparent!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;transform:none!important;font:inherit;line-height:1.5;color:#586579!important;white-space:nowrap}
.audit-detail .detail-tabs>button[role=tab].active{color:#2987cf!important;border-bottom-color:#2987cf!important}
